function costPlanAreaHtml(){const rows=costPlanRows(),planned=rows.reduce((sum,item)=>sum+item.planned,0),actual=rows.reduce((sum,item)=>sum+item.actual,0),difference=planned-actual,percent=planned>0?actual/planned*100:(actual>0?100:0);return`<div class="finance-area-head"><div><h3>Plano de custos</h3><p>Custos fixos planejados e despesas realizadas em ${esc(costPlanMonthLabel(activeCostMonth))}.</p></div><label><span>Mês</span><input id="costPlanMonth" type="month" value="${esc(activeCostMonth)}"></label></div><div class="finance-summary"><article><span>Total planejado</span><b>${money(planned)}</b></article><article><span>Total realizado</span><b>${money(actual)}</b></article><article><span>Percentual consumido</span><b>${percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</b></article><article class="finance-summary-total"><span>Saldo do orçamento</span><b>${money(difference)}</b></article></div><form id="costPlanForm"><div class="table-card finance-table"><table><thead><tr><th>Categoria</th><th>Planejado</th><th>Realizado</th><th>Diferença</th><th>Consumido</th></tr></thead><tbody>${rows.map(item=>`<tr data-cost-category="${esc(item.category)}"><td><b>${esc(item.category)}</b></td><td><input class="cost-plan-value" type="number" min="0" step="0.01" value="${item.planned.toFixed(2)}" aria-label="Valor planejado para ${esc(item.category)}"></td><td>${money(item.actual)}</td><td><b>${money(item.difference)}</b></td><td>${item.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</td></tr>`).join('')}</tbody></table></div><button class="primary wide">Salvar plano de custos</button></form>`}
function wireCostPlan(target){target.querySelector('#costPlanMonth').onchange=event=>{activeCostMonth=event.target.value||new Date().toISOString().slice(0,7);renderArea('Plano de custos')};target.querySelector('#costPlanForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter,items=[...event.currentTarget.querySelectorAll('[data-cost-category]')].map(row=>({category:row.dataset.costCategory,planned:Number(row.querySelector('.cost-plan-value').value)||0}));button.disabled=true;button.textContent='Salvando…';try{costPlans=await saveCostPlan(activeCostMonth,items);renderArea('Plano de custos');alert('Plano de custos salvo.')}catch(error){button.disabled=false;button.textContent='Salvar plano de custos';alert(error.message)}}}

function supplierAreaHtml(){const week=workWeek(localDateOnly(new Date())),luizinhoTotal=currentLuizinhoTotal(),retificaTotal=retificaBalance();if(activeSupplier==='luizinho'){const rows=[...supplierSettlements.luizinho].sort((a,b)=>String(b.date).localeCompare(String(a.date)));return`<div class="finance-area-head"><div><h3>Acerto fornecedores</h3><p>Notas por itens do Luizinho integradas ao estoque.</p></div><button class="primary add-supplier">＋ Incluir nota</button></div><div class="cash-account-tabs supplier-tabs"><button data-supplier="luizinho" class="active">Acerto Luizinho</button><button data-supplier="retifica">Acerto Retífica</button></div><div class="finance-summary"><article><span>Notas desta semana</span><b>${money(luizinhoTotal)}</b><small>${date(week.start)} a ${date(week.end)}</small></article><article class="finance-summary-total"><span>Vencimento do acerto</span><b>${date(nextSupplierMonday(week.start))}</b><small>Conta a pagar gerada automaticamente</small></article></div><div class="table-card finance-table supplier-table"><table><thead><tr><th>Data</th><th>Itens</th><th>Veículo</th><th>Valor total</th><th></th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${esc(item.description)}</b><small>${item.items?.length?`${item.items.length} item(ns) · ${item.items.map(part=>`${part.quantity}× ${part.code||'sem código'}`).join(' · ')}`:'Nota anterior sem itens detalhados'}</small></td><td>${esc(item.vehicle||'—')}</td><td><b>${money(item.amount)}</b></td><td><div class="finance-row-actions"><button class="secondary edit-supplier" data-id="${item.id}">Editar</button><button class="danger delete-supplier" data-id="${item.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="5">Nenhuma nota do Luizinho lançada.</td></tr>'}</tbody></table></div>`}const chronological=[...supplierSettlements.retifica].sort((a,b)=>String(a.date).localeCompare(String(b.date))||String(a.createdAt).localeCompare(String(b.createdAt)));let balance=0;chronological.forEach(item=>item.balance=balance+=Number(item.debit||0)-Number(item.paid||0));const rows=[...chronological].reverse();return`<div class="finance-area-head"><div><h3>Acerto fornecedores</h3><p>Conta-corrente de valores devidos e pagos à Retífica.</p></div><button class="primary add-supplier">＋ Incluir movimento</button></div><div class="cash-account-tabs supplier-tabs"><button data-supplier="luizinho">Acerto Luizinho</button><button data-supplier="retifica" class="active">Acerto Retífica</button></div><div class="finance-summary"><article class="finance-summary-total"><span>Saldo devedor da Retífica</span><b>${money(retificaTotal)}</b><small>Considerado na saúde da empresa</small></article></div><div class="table-card finance-table supplier-table"><table><thead><tr><th>Data</th><th>Descrição</th><th>Veículo</th><th>Valor devedor</th><th>Valor pago</th><th>Saldo</th><th></th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${esc(item.description)}</b></td><td>${esc(item.vehicle||'—')}</td><td>${item.debit?money(item.debit):'—'}</td><td>${item.paid?money(item.paid):'—'}</td><td><b>${money(item.balance)}</b></td><td><div class="finance-row-actions"><button class="secondary edit-supplier" data-id="${item.id}">Editar</button><button class="danger delete-supplier" data-id="${item.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="7">Nenhum movimento da Retífica lançado.</td></tr>'}</tbody></table></div>`}
function nextSupplierMonday(weekStart){const value=new Date(`${weekStart}T12:00:00`);value.setDate(value.getDate()+7);return localDateOnly(value)}
function luizinhoItemRow(item={},index=0){const quantity=Math.max(1,Number(item.quantity||1)),unitValue=Math.max(0,Number(item.unitValue||0));return`<tr data-note-item="${index}"><td><input data-note-field="code" value="${esc(item.code||'')}" placeholder="Código"></td><td><input data-note-field="brand" value="${esc(item.brand||'')}" placeholder="Marca"></td><td><input data-note-field="quantity" type="number" min="1" step="1" value="${quantity}"></td><td><input data-note-field="description" value="${esc(item.description||'')}" placeholder="Descrição"></td><td><input data-note-field="unitValue" type="number" min="0.01" step="0.01" value="${unitValue||''}"></td><td><b data-note-total>${money(quantity*unitValue)}</b></td><td><button type="button" class="remove-line remove-note-item" aria-label="Remover item">×</button></td></tr>`}
function openLuizinhoPopup(item){const popup=document.createElement('div'),draft=item?.items?.length?item.items.map(part=>({...part})):[item?.description?{code:'',brand:'',quantity:1,description:item.description,unitValue:Number(item.amount||0)}:{code:'',brand:'',quantity:1,description:'',unitValue:0}];document.querySelector('.finance-popup')?.remove();popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card supplier-note-popup"><span class="eyebrow">${item?'EDITAR':'NOVA'} NOTA</span><h3>Acerto Luizinho</h3><div class="grid two"><label><span>Data</span><input id="supplierDate" type="date" value="${esc(item?.date||localDateOnly(new Date()))}" required></label><label><span>Veículo</span><input id="supplierVehicle" value="${esc(item?.vehicle||'')}" placeholder="Placa ou modelo"></label></div><div class="budget-table supplier-note-items"><table><thead><tr><th>Código</th><th>Marca</th><th>Quantidade</th><th>Descrição</th><th>Valor unitário</th><th>Valor total</th><th></th></tr></thead><tbody id="luizinhoNoteItems">${draft.map(luizinhoItemRow).join('')}</tbody></table></div><div class="supplier-note-actions"><button type="button" class="secondary" id="addLuizinhoItem">＋ Incluir item</button><strong>Total da nota: <span id="luizinhoNoteTotal">${money(0)}</span></strong></div><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar nota e incluir no estoque</button></div></form>`;document.body.append(popup);const body=popup.querySelector('#luizinhoNoteItems'),refresh=()=>{let total=0;body.querySelectorAll('[data-note-item]').forEach(row=>{const quantity=Math.max(1,Number(row.querySelector('[data-note-field="quantity"]').value||1)),unitValue=Math.max(0,Number(row.querySelector('[data-note-field="unitValue"]').value||0)),line=quantity*unitValue;row.querySelector('[data-note-total]').textContent=money(line);total+=line});popup.querySelector('#luizinhoNoteTotal').textContent=money(total)},lookupCode=input=>{const code=input.value.trim().toUpperCase();input.value=code;if(!code)return;const found=supplierStock.find(stock=>String(stock.code||'').trim().toUpperCase()===code);if(!found)return;const row=input.closest('[data-note-item]'),description=row.querySelector('[data-note-field="description"]'),brand=row.querySelector('[data-note-field="brand"]');description.value=found.description||description.value;brand.value=found.application||brand.value};popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('#addLuizinhoItem').onclick=()=>{body.insertAdjacentHTML('beforeend',luizinhoItemRow({},body.children.length));refresh()};body.addEventListener('input',event=>{if(event.target.matches('[data-note-field="code"]'))lookupCode(event.target);refresh()});body.addEventListener('click',event=>{const remove=event.target.closest('.remove-note-item');if(!remove)return;if(body.children.length===1)return alert('A nota precisa ter pelo menos um item.');remove.closest('tr').remove();refresh()});popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const items=[...body.querySelectorAll('[data-note-item]')].map(row=>({code:row.querySelector('[data-note-field="code"]').value.trim().toUpperCase(),brand:row.querySelector('[data-note-field="brand"]').value.trim(),quantity:Number(row.querySelector('[data-note-field="quantity"]').value),description:row.querySelector('[data-note-field="description"]').value.trim(),unitValue:Number(row.querySelector('[data-note-field="unitValue"]').value)}));if(items.some(part=>!part.description||part.quantity<=0||part.unitValue<=0))return alert('Preencha descrição, quantidade e valor unitário de todos os itens.');const button=event.submitter,data={date:popup.querySelector('#supplierDate').value,vehicle:popup.querySelector('#supplierVehicle').value.trim(),items};button.disabled=true;button.textContent='Salvando…';try{supplierSettlements=item?await updateLuizinhoNote(item.id,data):await saveLuizinhoNote(data);[records,supplierStock]=await Promise.all([readFinance(),readStock()]);popup.remove();await loadDashboard()}catch(error){button.disabled=false;button.textContent='Salvar nota e incluir no estoque';alert(error.message)}};refresh()}
function openSupplierPopup(id=''){const type=activeSupplier,item=supplierSettlements[type].find(row=>row.id===id);if(type==='luizinho')return openLuizinhoPopup(item);const popup=document.createElement('div');document.querySelector('.finance-popup')?.remove();popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">${item?'EDITAR':'NOVO'} ACERTO</span><h3>Retífica</h3><label><span>Data</span><input id="supplierDate" type="date" value="${esc(item?.date||localDateOnly(new Date()))}" required></label><label><span>Descrição</span><input id="supplierDescription" value="${esc(item?.description||'')}" required></label><label><span>Veículo</span><input id="supplierVehicle" value="${esc(item?.vehicle||'')}" placeholder="Placa ou modelo"></label><div class="grid two"><label><span>Valor devedor</span><input id="supplierDebit" type="number" min="0" step="0.01" value="${Number(item?.debit||0)||''}"></label><label><span>Valor pago</span><input id="supplierPaid" type="number" min="0" step="0.01" value="${Number(item?.paid||0)||''}"></label></div><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,data={date:popup.querySelector('#supplierDate').value,description:popup.querySelector('#supplierDescription').value.trim(),vehicle:popup.querySelector('#supplierVehicle').value.trim(),debit:Number(popup.querySelector('#supplierDebit').value)||0,paid:Number(popup.querySelector('#supplierPaid').value)||0};if(!data.debit&&!data.paid)return alert('Informe um valor devedor ou um valor pago.');button.disabled=true;button.textContent='Salvando…';try{supplierSettlements=item?await updateSupplierSettlement(type,item.id,data):await saveSupplierSettlement(type,data);records=await readFinance();popup.remove();await loadDashboard()}catch(error){button.disabled=false;button.textContent='Salvar';alert(error.message)}}}
function wireSupplierArea(target){target.querySelectorAll('[data-supplier]').forEach(button=>button.onclick=()=>{activeSupplier=button.dataset.supplier;renderArea('Acerto fornecedores')});target.querySelector('.add-supplier').onclick=()=>openSupplierPopup();target.querySelectorAll('.edit-supplier').forEach(button=>button.onclick=()=>openSupplierPopup(button.dataset.id));target.querySelectorAll('.delete-supplier').forEach(button=>button.onclick=async()=>{const item=supplierSettlements[activeSupplier].find(row=>row.id===button.dataset.id);if(!item||!confirm(`Excluir "${item.description}"?${activeSupplier==='luizinho'&&item.stockApplied?'\n\nA entrada correspondente será revertida no estoque.':''}`))return;button.disabled=true;try{supplierSettlements=activeSupplier==='luizinho'?await deleteLuizinhoNote(item.id):await deleteSupplierSettlement(activeSupplier,item.id);[records,supplierStock]=await Promise.all([readFinance(),readStock()]);await loadDashboard()}catch(error){button.disabled=false;alert(error.message)}})}

function expensesAreaHtml(){const reserveEntries=cashProfitEvents().map(item=>({date:item.date,kind:'Entrada',category:'Reserva para despesas',description:`Reserva de 30% do lucro recebido da O.S. #${item.order.number}`,amount:item.reserve,source:`O.S. #${item.order.number}`})).filter(item=>item.amount>0),expenseEntries=records.filter(record=>record.category==='Fluxo de caixa'&&record.status==='Realizado'&&record.kind==='Saída'&&expenseKind(record.description)).map(record=>({date:record.dueDate||localDateOnly(record.createdAt),kind:'Saída',category:expenseKind(record.description),description:record.description,amount:Number(record.amount||0),source:cashAccount(record)})),chronological=[...reserveEntries,...expenseEntries].sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))||a.kind.localeCompare(b.kind));let balance=0;chronological.forEach(item=>item.balance=balance+=item.kind==='Entrada'?item.amount:-item.amount);const entries=reserveEntries.reduce((sum,item)=>sum+item.amount,0),exits=expenseEntries.reduce((sum,item)=>sum+item.amount,0),rows=[...chronological].reverse();return`<div class="finance-area-head"><div><h3>Despesas</h3><p>30% do lucro real recebido como entrada e despesas identificadas nos caixas como saída.</p></div></div><div class="finance-summary"><article><span>Reserva · 30% do lucro recebido</span><b>${money(entries)}</b></article><article><span>Despesas identificadas</span><b>${money(exits)}</b></article><article class="finance-summary-total"><span>Saldo disponível</span><b>${money(entries-exits)}</b></article></div><p class="archive-note">Palavras identificadas: ${EXPENSE_RULES.map(([label])=>label).join(' · ')}</p><div class="table-card finance-table partner-commission-table expense-ledger-table"><table><thead><tr><th>Data</th><th>Movimento</th><th>Classificação</th><th>Origem</th><th>Descrição</th><th>Entrada</th><th>Saída</th><th>Saldo</th></tr></thead><tbody>${rows.length?rows.map(item=>`<tr><td>${date(item.date)}</td><td><b>${item.kind}</b></td><td>${esc(item.category)}</td><td>${esc(item.source)}</td><td>${esc(item.description)}</td><td>${item.kind==='Entrada'?money(item.amount):'—'}</td><td>${item.kind==='Saída'?money(item.amount):'—'}</td><td><b>${money(item.balance)}</b></td></tr>`).join(''):'<tr><td colspan="8">Nenhuma reserva ou despesa identificada.</td></tr>'}</tbody></table></div>`}
function balancePayableWindow(value=localDateOnly(new Date())){const week=workWeek(value),saturday=new Date(`${week.start}T12:00:00`);saturday.setDate(saturday.getDate()-2);return{start:localDateOnly(saturday),end:week.end}}
function payableForBalance(record,value=localDateOnly(new Date())){if(record.category!=='Conta a pagar'||record.status==='Realizado'||!record.dueDate)return false;const due=String(record.dueDate).slice(0,10),range=balancePayableWindow(value);return due<range.start||(due>=range.start&&due<=range.end)}
function totals(){const orders=localOrders(),receivable=records.filter(r=>readyReceivable(r,orders)&&r.status!=='Realizado').reduce((s,r)=>s+r.amount,0),payable=records.filter(record=>payableForBalance(record)).reduce((s,r)=>s+r.amount,0),commissions=records.filter(r=>r.category==='Comissões'&&r.status!=='Realizado').reduce((s,r)=>s+r.amount,0),bb=cashBalance('Banco do Brasil'),ml=cashBalance('Mercado Livre'),cash=cashBalance('Dinheiro'),balance=bb+ml+cash;return{receivable,payable,commissions,bb,ml,cash,balance,balanceSheet:balance+receivable-payable-commissions}}
const totalsWithoutPartnerCommissions=totals;
totals=function(){const result=totalsWithoutPartnerCommissions(),partnerCommissions=currentPartnerCommissions();return{...result,partnerCommissions,balanceSheet:result.balanceSheet-partnerCommissions}};

function companyHealth(){
  const total=totals(),month=new Date().toISOString().slice(0,7),plan=costPlanRows(month),planned=plan.reduce((sum,item)=>sum+item.planned,0),actualFixed=plan.reduce((sum,item)=>sum+item.actual,0),remainingFixed=Math.max(0,planned-actualFixed),cashMonth=records.filter(record=>record.category==='Fluxo de caixa'&&record.status==='Realizado'&&String(record.dueDate||record.createdAt||'').slice(0,7)===month),inflows=cashMonth.filter(record=>record.kind==='Entrada').reduce((sum,record)=>sum+Number(record.amount||0),0),outflows=cashMonth.filter(record=>record.kind==='Saída').reduce((sum,record)=>sum+Number(record.amount||0),0),monthlyResult=inflows-outflows,retifica=Math.max(0,retificaBalance()),resources=Math.max(0,total.balance)+Math.max(0,total.receivable),commitments=Math.max(0,total.payable)+Math.max(0,total.commissions)+Math.max(0,total.partnerCommissions)+remainingFixed+retifica,coverage=commitments>0?resources/commitments:resources>0?2:1,coveragePoints=Math.min(70,Math.max(0,coverage/1.5*70)),cashPoints=monthlyResult>=0?30:Math.max(0,30-(Math.abs(monthlyResult)/Math.max(inflows,1))*30),score=Math.round(coveragePoints+cashPoints),level=score>=80?'Saudável':score>=60?'Estável':score>=40?'Atenção':'Crítica',tone=score>=80?'healthy':score>=60?'stable':score>=40?'attention':'critical';
  return{score,level,tone,resources,commitments,coverage,monthlyResult,remainingFixed,retifica,inflows,outflows}
}
function companyHealthHtml(){const health=companyHealth();return`<section class="company-health company-health-${health.tone}"><div class="company-health-head"><div><span class="eyebrow">SAÚDE DA EMPRESA</span><h3>${health.level}</h3><p>Capacidade financeira calculada com os dados atuais do aplicativo.</p></div><strong>${health.score}<small>/100</small></strong></div><progress max="100" value="${health.score}" aria-label="Saúde da empresa: ${health.score} de 100"></progress><div class="finance-summary"><article><span>Recursos disponíveis</span><b>${money(health.resources)}</b><small>Caixas + valores a receber</small></article><article><span>Compromissos previstos</span><b>${money(health.commitments)}</b><small>Contas, comissões, Retífica e custos fixos restantes</small></article><article><span>Saldo devedor da Retífica</span><b>${money(health.retifica)}</b><small>Incluído nos compromissos</small></article><article><span>Cobertura financeira</span><b>${health.coverage.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}×</b><small>Recursos ÷ compromissos</small></article><article><span>Resultado de caixa do mês</span><b>${money(health.monthlyResult)}</b><small>Entradas − saídas realizadas</small></article></div><small class="company-health-method">A nota atribui até 70 pontos à cobertura dos compromissos e até 30 pontos ao resultado mensal. Custos fixos padrão: ${money([...FIXED_MONTHLY_COSTS.values()].reduce((sum,value)=>sum+value,0))} por mês.</small></section>`}

function dashboardHtml(){const total=totals();return`<div class="admin-head"><div><span class="eyebrow">GESTÃO FINANCEIRA NO BANCO</span><h2>Financeiro</h2></div><div class="finance-row-actions"><button class="secondary" id="manageUsers">Gerenciar usuários</button><button class="primary" id="addMechanic">＋ Adicionar mecânico</button></div></div><div class="finance-summary"><article><span>Contas a receber · O.S. prontas</span><b>${money(total.receivable)}</b></article><article><span>Contas a pagar</span><b>${money(total.payable)}</b></article><article><span>Banco do Brasil</span><b>${money(total.bb)}</b></article><article><span>Mercado Livre</span><b>${money(total.ml)}</b></article><article><span>Dinheiro</span><b>${money(total.cash)}</b></article><article class="finance-summary-total"><span>Saldo total em caixa</span><b>${money(total.balance)}</b></article><article><span>Comissões a pagar</span><b>${money(total.commissions)}</b></article><article class="finance-summary-total finance-balance-sheet"><span>Balanço</span><b>${money(total.balanceSheet)}</b><small>Caixas + a receber − contas a pagar − comissões</small></article></div><div class="home-menu finance-home-menu"><button data-finance-area="Fluxo de caixa"><i>R$</i><span>Caixa</span></button><button data-finance-area="Conta a pagar"><i>−</i><span>Contas a pagar</span></button><button data-finance-area="Conta a receber"><i>＋</i><span>Contas a receber</span></button><button data-finance-area="Comissões"><i>%</i><span>Comissões</span></button></div><section id="financeArea"></section>`}
const dashboardHtmlWithoutProfit=dashboardHtml;
dashboardHtml=function(){const partnerCommissions=totals().partnerCommissions,week=workWeek(localDateOnly(new Date()));return dashboardHtmlWithoutProfit().replace('<div class="finance-summary">',companyHealthHtml()+'<div class="finance-summary">').replace('<article class="finance-summary-total finance-balance-sheet">',`<article><span>Comissões dos sócios · a pagar</span><b>${money(partnerCommissions)}</b></article><article><span>Notas Luizinho · semana</span><b>${money(currentLuizinhoTotal())}</b><small>${date(week.start)} a ${date(week.end)}</small></article><article><span>Saldo devedor da Retífica</span><b>${money(retificaBalance())}</b></article><article class="finance-summary-total finance-balance-sheet">`).replace('Caixas + a receber − contas a pagar − comissões</small>','Caixas + a receber − contas vencidas ou desta semana − comissões da equipe − comissões dos sócios</small>').replace('</div><section id="financeArea">','<button data-finance-area="Lucro"><i>↗</i><span>Lucro</span></button><button data-finance-area="Comissões sócios"><i>%</i><span>Comissões sócios</span></button><button data-finance-area="Despesas"><i>−</i><span>Despesas</span></button><button data-finance-area="Plano de custos"><i>▤</i><span>Plano de custos</span></button><button data-finance-area="Acerto fornecedores"><i>▦</i><span>Acerto fornecedores</span></button></div><section id="financeArea">')};
const monday=value=>{const d=new Date(`${value}T12:00`),day=d.getDay();d.setDate(d.getDate()+(day===0?-6:1-day));return d.toISOString().slice(0,10)};
const friday=value=>{const d=new Date(`${monday(value)}T12:00`);d.setDate(d.getDate()+4);return d.toISOString().slice(0,10)};
function cashTimeline(all){let balance=0;const chronological=all.filter(record=>cashAccount(record)===activeCashAccount&&record.status==='Realizado').sort((a,b)=>String(a.dueDate||'').localeCompare(String(b.dueDate||''))||String(a.createdAt||'').localeCompare(String(b.createdAt||''))).map(record=>({...record,runningBalance:balance+=record.kind==='Saída'?-record.amount:record.amount})),days=new Map();for(const record of chronological){if(!days.has(record.dueDate))days.set(record.dueDate,[]);days.get(record.dueDate).push(record)}const rows=[...days.entries()].sort(([a],[b])=>String(b).localeCompare(String(a))).map(([day,items])=>{const entries=items.reduce((sum,item)=>sum+(item.kind==='Entrada'?item.amount:0),0),exits=items.reduce((sum,item)=>sum+(item.kind==='Saída'?item.amount:0),0),closing=items.at(-1)?.runningBalance||0,transactions=[...items].reverse().map(record=>`<tr><td>${date(record.dueDate)}</td><td><b>${esc(record.description)}</b></td><td>${record.kind==='Entrada'?`<b>${money(record.amount)}</b>`:'—'}</td><td>${record.kind==='Saída'?`<b>${money(record.amount)}</b>`:'—'}</td><td><b>${money(record.runningBalance)}</b></td><td><div class="finance-row-actions"><button class="secondary edit-finance" data-id="${record.id}">Editar</button><button class="danger delete-finance" data-id="${record.id}">Excluir</button></div></td></tr>`).join('');return`${transactions}<tr class="cash-day-closing"><td>${date(day)}</td><td><b>Fechamento do dia</b></td><td>${money(entries)}</td><td>${money(exits)}</td><td><b>${money(closing)}</b></td><td></td></tr>`}).join('');return{balance,rows}}
function renderArea(area=activeArea){
  activeArea=area;
  document.querySelectorAll('[data-finance-area]').forEach(button=>button.classList.toggle('active',button.dataset.financeArea===area));
  const target=$('#financeArea'),label=area==='Fluxo de caixa'?'Caixa':area,filtered=records.filter(record=>record.category===area),all=area==='Conta a pagar'?[...filtered].sort((a,b)=>String(a.dueDate||'9999-12-31').localeCompare(String(b.dueDate||'9999-12-31'))||String(a.createdAt||'').localeCompare(String(b.createdAt||''))):filtered;
  if(area==='Fluxo de caixa'){
    const timeline=cashTimeline(all),balance=timeline.balance,totalCash=CASH_ACCOUNTS.reduce((sum,account)=>sum+cashBalance(account),0);
    target.innerHTML=`<div class="finance-area-head"><div><h3>Caixa</h3><p>Saldo ${esc(activeCashAccount)}: <b>${money(balance)}</b></p><p>Soma de todos os caixas: <b>${money(totalCash)}</b></p></div><button class="primary add-finance">＋ Adicionar</button></div><div class="cash-account-tabs">${CASH_ACCOUNTS.map(name=>`<button data-cash-account="${name}" class="${name===activeCashAccount?'active':''}">${name}</button>`).join('')}</div><div class="table-card finance-table cash-table"><table><thead><tr><th>Data</th><th>Descrição</th><th>Entrada</th><th>Saída</th><th>Saldo</th><th></th></tr></thead><tbody>${timeline.rows||'<tr><td colspan="6">Nenhum lançamento neste caixa.</td></tr>'}</tbody></table></div>`;
    target.querySelectorAll('[data-cash-account]').forEach(button=>button.onclick=()=>{activeCashAccount=button.dataset.cashAccount;renderArea('Fluxo de caixa')});
  }else if(area==='Conta a receber'){
    const orders=localOrders(),pending=all.filter(record=>record.status!=='Realizado'&&readyReceivable(record,orders)),archived=all.filter(record=>record.status==='Realizado'),list=showReceivedArchive?archived:pending,total=pending.reduce((sum,record)=>sum+record.amount,0);
    target.innerHTML=`<div class="finance-area-head"><div><h3>Contas a receber</h3><p>Somente O.S. prontas para entrega: <b>${money(total)}</b></p></div><button class="secondary toggle-received-archive">${showReceivedArchive?'Ver a receber':`Recebidas arquivadas (${archived.length})`}</button></div><div class="table-card finance-table"><table><thead><tr><th>Registro</th><th>Data</th><th>Tipo</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${list.length?list.map(record=>`<tr><td><b>${esc(record.description)}</b>${record.paymentType?`<small>${esc(record.paymentType)}</small>`:''}</td><td>${date(record.dueDate)}</td><td>${esc(record.kind)}</td><td><b>${money(record.amount)}</b></td><td>${record.status==='Realizado'?'Recebida · Arquivada':'A receber'}</td><td><div class="finance-row-actions">${record.status!=='Realizado'?`<button class="secondary mark-paid" data-id="${record.id}">Marcar recebida</button>`:'✓'}<button class="danger delete-finance" data-id="${record.id}">Excluir</button></div></td></tr>`).join(''):`<tr><td colspan="6">${showReceivedArchive?'Nenhuma conta recebida arquivada.':'Nenhuma O.S. pronta com valor a receber.'}</td></tr>`}</tbody></table></div>`;
    target.querySelector('.toggle-received-archive').onclick=()=>{showReceivedArchive=!showReceivedArchive;renderArea('Conta a receber')};
  }else if(area==='Comissões'){
    const mechanicRecords=all.filter(record=>String(record.mechanic).toLowerCase()===activeMechanic.toLowerCase()),pending=mechanicRecords.filter(record=>record.status!=='Realizado'),archived=mechanicRecords.filter(record=>record.status==='Realizado'),list=showCommissionArchive?archived:pending,total=pending.reduce((sum,record)=>sum+record.amount,0);
    target.innerHTML=`<div class="finance-area-head"><div><h3>Comissões</h3><p>A pagar para ${esc(activeMechanic)}: <b>${money(total)}</b></p></div><div class="finance-row-actions"><button class="secondary toggle-commission-archive">${showCommissionArchive?'Ver comissões a pagar':`Pagas arquivadas (${archived.length})`}</button><button class="primary add-finance">＋ Adicionar</button></div></div><div class="mechanic-tabs">${activeMechanics().map(name=>`<button data-mechanic="${name}" class="${name===activeMechanic?'active':''}">${name}</button>`).join('')}</div><div class="table-card finance-table"><table><thead><tr><th>Semana</th><th>Registro</th><th>Data</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${list.length?list.map(record=>{const start=record.weekStart||monday(record.dueDate);return`<tr><td><b>${date(start)} a ${date(friday(start))}</b></td><td>${esc(record.description)}</td><td>${date(record.dueDate)}</td><td><b>${money(record.amount)}</b></td><td>${record.status==='Realizado'?'Paga · Arquivada':'A pagar'}</td><td><div class="finance-row-actions">${record.status!=='Realizado'?`<button class="secondary mark-paid" data-id="${record.id}">Marcar paga</button>`:'✓'}<button class="danger delete-finance" data-id="${record.id}">Excluir</button></div></td></tr>`}).join(''):`<tr><td colspan="6">${showCommissionArchive?'Nenhuma comissão paga arquivada.':'Nenhuma comissão a pagar.'}</td></tr>`}</tbody></table></div>`;
    target.querySelector('.toggle-commission-archive').onclick=()=>{showCommissionArchive=!showCommissionArchive;renderArea('Comissões')};
    document.querySelectorAll('[data-mechanic]').forEach(button=>button.onclick=()=>{activeMechanic=button.dataset.mechanic;showCommissionArchive=false;renderArea('Comissões')});
  }else{
    const total=all.reduce((sum,record)=>sum+(record.kind==='Saída'?-record.amount:record.amount),0);
    target.innerHTML=`<div class="finance-area-head"><div><h3>${label}</h3><p>Total: <b>${money(total)}</b></p></div><button class="primary add-finance">＋ Adicionar</button></div><div class="table-card finance-table"><table><thead><tr><th>Registro</th><th>Data</th><th>Tipo</th><th>Valor</th><th>Status</th><th></th></tr></thead><tbody>${all.length?all.map(record=>`<tr><td><b>${esc(record.description)}</b>${record.paymentType?`<small>${esc(record.paymentType)}</small>`:''}</td><td>${date(record.dueDate)}</td><td>${esc(record.kind)}</td><td><b>${money(record.amount)}</b></td><td>${esc(record.status)}</td><td><div class="finance-row-actions">${record.status!=='Realizado'?`<button class="secondary mark-paid" data-id="${record.id}">Marcar realizado</button>`:'✓'}<button class="danger delete-finance" data-id="${record.id}">Excluir</button></div></td></tr>`).join(''):'<tr><td colspan="6">Nenhum lançamento nesta aba.</td></tr>'}</tbody></table></div>`;
  }
  target.querySelector('.add-finance')?.addEventListener('click',()=>openFinancePopup(area));
  target.querySelectorAll('.mark-paid').forEach(button=>button.onclick=()=>markPaid(button.dataset.id));
  target.querySelectorAll('.edit-finance').forEach(button=>button.onclick=()=>openCashEditPopup(button.dataset.id));
  target.querySelectorAll('.delete-finance').forEach(button=>button.onclick=()=>removeFinance(button.dataset.id));
}
const renderAreaWithoutProfit=renderArea;
async function exportFinancePreview(button,modal,title,print=false){const original=button.textContent;button.disabled=true;button.textContent='Gerando PDF…';try{await exportReportPdf(modal.querySelector('.report-pdf-sheet'),title,{print})}catch(error){alert(`Não foi possível gerar o PDF.\n\n${error.message}`)}finally{button.disabled=false;button.textContent=original}}
function financePdfPreview(title,target){document.querySelector('.finance-profit-pdf')?.remove();const content=target.cloneNode(true);content.querySelector('.partner-tabs')?.remove();content.querySelector('.partner-period-tabs')?.remove();content.querySelectorAll('button').forEach(button=>button.remove());const modal=document.createElement('div');modal.className='report-pdf-preview finance-profit-pdf';modal.innerHTML=`<div class="report-pdf-sheet"><header><div class="report-company"><img src="${new URL('../official-logo.png',import.meta.url).href}" alt="Logo Cortez Garage"><div><h2>Cortez Garage mecânica e auto elétrica</h2><p>Av. Brasil, 5452, Bamerindus, Itapoá - SC</p><p>Cel: (47) 99124-7442 · CNPJ 57.757.919/0001-41</p></div></div><div><span>RELATÓRIO FINANCEIRO</span><h1>${esc(title)}</h1><p>Gerado em ${new Date().toLocaleString('pt-BR')}</p></div></header><main>${content.innerHTML}</main><footer><button class="secondary close-finance-pdf">Voltar</button><button class="secondary print-finance-pdf">Imprimir PDF</button><button class="primary save-finance-pdf">Salvar PDF</button></footer></div>`;modal.querySelector('.close-finance-pdf').onclick=()=>modal.remove();modal.querySelector('.print-finance-pdf').onclick=event=>exportFinancePreview(event.currentTarget,modal,title,true);modal.querySelector('.save-finance-pdf').onclick=event=>exportFinancePreview(event.currentTarget,modal,title);document.body.append(modal)}
function financePdfTitle(area){if(area==='Fluxo de caixa')return`Caixa — ${activeCashAccount}`;if(area==='Comissões')return`Comissões — ${activeMechanic}`;if(area==='Lucro')return'Lucro real e líquido';if(area==='Comissões sócios')return`Comissões dos sócios — ${activePartner} — ${partnerArchive?'Semanas arquivadas':'Semana atual'}`;if(area==='Plano de custos')return`Plano de custos — ${costPlanMonthLabel(activeCostMonth)}`;return area}function wireFinancePdf(area,target){const head=target.querySelector('.finance-area-head');if(!head||head.querySelector('.finance-area-pdf'))return;const button=document.createElement('button');button.type='button';button.className='primary finance-area-pdf';button.textContent='Imprimir PDF';button.onclick=()=>financePdfPreview(financePdfTitle(area),target);head.append(button)}
renderArea=function(area=activeArea){if(!['Lucro','Comissões sócios','Despesas','Plano de custos','Acerto fornecedores'].includes(area)){const result=renderAreaWithoutProfit(area),target=$('#financeArea');if(target)wireFinancePdf(area,target);return result}activeArea=area;document.querySelectorAll('[data-finance-area]').forEach(button=>button.classList.toggle('active',button.dataset.financeArea===area));const target=$('#financeArea');if(!target)return;if(area==='Lucro'){target.innerHTML=profitAreaHtml();wireFinancePdf(area,target);return}if(area==='Despesas'){target.innerHTML=expensesAreaHtml();wireFinancePdf(area,target);return}if(area==='Plano de custos'){target.innerHTML=costPlanAreaHtml();wireCostPlan(target);wireFinancePdf(area,target);return}if(area==='Acerto fornecedores'){target.innerHTML=supplierAreaHtml();wireSupplierArea(target);wireFinancePdf(area,target);return}target.innerHTML=partnerCommissionsHtml(activePartner);target.querySelectorAll('[data-partner]').forEach(button=>button.onclick=()=>{activePartner=button.dataset.partner;renderArea('Comissões sócios')});target.querySelectorAll('[data-partner-archive]').forEach(button=>button.onclick=()=>{partnerArchive=button.dataset.partnerArchive==='archived';renderArea('Comissões sócios')});wireFinancePdf(area,target)};
async function removeFinance(id){const record=records.find(item=>item.id===id);if(!record||!confirm(`Excluir "${record.description}" no valor de ${money(record.amount)}?`))return;try{await deleteFinanceRecord(id);await loadDashboard()}catch(error){alert(error.message)}}
function openCashEditPopup(id){const record=records.find(item=>item.id===id);if(!record)return;document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">EDITAR LANÇAMENTO</span><h3>${esc(cashAccount(record))}</h3><label><span>Caixa</span><select id="editFinanceAccount">${CASH_ACCOUNTS.map(name=>`<option ${name===cashAccount(record)?'selected':''}>${name}</option>`).join('')}</select></label><label><span>Data</span><input id="editFinanceDate" type="date" value="${esc(record.dueDate)}" required></label><label><span>Descrição</span><input id="editFinanceDescription" value="${esc(record.description)}" required></label><label><span>Valor</span><input id="editFinanceAmount" type="number" min="0.01" step="0.01" value="${Number(record.amount)}" required></label><label><span>Tipo</span><select id="editFinanceKind"><option ${record.kind==='Entrada'?'selected':''}>Entrada</option><option ${record.kind==='Saída'?'selected':''}>Saída</option></select></label><small id="editFinanceAutoKind" hidden>Classificado automaticamente como Saída.</small><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar alterações</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();const description=popup.querySelector('#editFinanceDescription'),kind=popup.querySelector('#editFinanceKind'),note=popup.querySelector('#editFinanceAutoKind'),syncKind=()=>{const automatic=automaticCashExpense(description.value);if(automatic)kind.value='Saída';kind.disabled=automatic;note.hidden=!automatic};description.addEventListener('input',syncKind);syncKind();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,automatic=automaticCashExpense(description.value);button.disabled=true;button.textContent='Salvando…';try{await updateFinanceRecord(record.id,{category:'Fluxo de caixa',kind:automatic?'Saída':kind.value,description:description.value.trim(),amount:Number(popup.querySelector('#editFinanceAmount').value),dueDate:popup.querySelector('#editFinanceDate').value,status:'Realizado',paymentType:popup.querySelector('#editFinanceAccount').value,mechanic:record.mechanic});records=await readFinance();activeCashAccount=popup.querySelector('#editFinanceAccount').value;popup.remove();await loadDashboard()}catch(error){button.disabled=false;button.textContent='Salvar alterações';alert(error.message)}}}

function openMechanicManager(){
  $('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><section class="form-card finance-form"><div class="form-head"><i>⚙</i><div><span class="eyebrow">EQUIPE DA OFICINA</span><h3>Cadastro de mecânicos</h3><p>Os mecânicos ativos aparecem nas O.S., nos serviços e nas comissões.</p></div></div><form id="mechanicForm"><label><span>Nome do mecânico</span><input id="mechanicName" autocomplete="name" maxlength="80" placeholder="Nome completo" required></label><button class="primary wide">Salvar mecânico</button></form><div class="table-card finance-table"><table><thead><tr><th>Mecânico</th><th>Status</th><th></th></tr></thead><tbody>${mechanics.map(item=>`<tr><td><b>${esc(item.name)}</b></td><td>${item.active?'Ativo':'Inativo'}</td><td><button class="${item.active?'secondary':'primary'} toggle-mechanic" data-name="${esc(item.name)}" data-active="${item.active?'false':'true'}">${item.active?'Desativar':'Ativar'}</button></td></tr>`).join('')}</tbody></table></div></section>`;
  $('#backAdmin').onclick=loadDashboard;
  $('#mechanicForm').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Salvando…';try{mechanics=await saveMechanic($('#mechanicName').value);openMechanicManager()}catch(error){button.disabled=false;button.textContent='Salvar mecânico';alert(error.message)}};
  document.querySelectorAll('.toggle-mechanic').forEach(button=>button.onclick=async()=>{button.disabled=true;try{mechanics=await setMechanicActive(button.dataset.name,button.dataset.active==='true');openMechanicManager()}catch(error){button.disabled=false;alert(error.message)}})
}

const USER_PERMISSION_LABELS={accessApp:'Acessar o aplicativo',manageValues:'Alterar serviços, peças e valores',viewDelivered:'Visualizar O.S. entregues',readyOrders:'Colocar veículo pronto para entrega'};
function userPermissionChecks(user,prefix='user'){return Object.entries(USER_PERMISSION_LABELS).map(([key,label])=>`<label class="check-item"><input type="checkbox" data-user-permission="${key}" ${user.permissions?.[key]?'checked':''}><span>✓</span>${label}</label>`).join('')}
function openUserManager(){
  const mechanicOptions=`<option value="" disabled selected>Selecione a agenda</option>`+agendaMechanics().map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');
  $('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><section class="form-card finance-form"><div class="form-head"><i>♙</i><div><span class="eyebrow">ACESSOS DO APLICATIVO</span><h3>Gerenciar usuários</h3><p>Cadastre usuários e determine o que cada um pode acessar.</p></div></div><form id="newManagedUser"><div class="grid two"><label><span>Nome</span><input id="managedUserName" required></label><label><span>E-mail</span><input id="managedUserEmail" type="email" required></label><label><span>Senha inicial</span><input id="managedUserPassword" type="password" minlength="6" required></label><label><span>Agenda individual</span><select id="managedUserMechanic" required>${mechanicOptions}</select></label></div><h4>Permissões iniciais</h4><div class="checkgrid" id="newUserPermissions">${userPermissionChecks({permissions:{accessApp:true,manageValues:false,viewDelivered:true,readyOrders:false}})}</div><button class="primary wide">Adicionar usuário</button></form><div class="managed-users-list">${managedUsers.map(user=>`<article class="detail managed-user-card" data-user-email="${esc(user.email)}"><div class="finance-area-head"><div><h3>${esc(user.name)}</h3><p>${esc(user.email)} · ${user.active?'Ativo':'Acesso bloqueado'}</p></div><button class="${user.active?'danger':'primary'} toggle-user-access" ${user.email===FINANCE_EMAIL?'disabled':''}>${user.active?'Bloquear acesso':'Liberar acesso'}</button></div><label><span>Agenda individual</span><select class="managed-user-mechanic" ${user.email===FINANCE_EMAIL?'disabled':'required'}>${user.email===FINANCE_EMAIL?'<option value="">Todas as agendas · proprietário</option>':`${user.agendaMechanic?'':`<option value="" disabled selected>Selecione a agenda</option>`}${agendaMechanics().map(name=>`<option value="${esc(name)}" ${user.agendaMechanic===name?'selected':''}>${esc(name)}</option>`).join('')}`}</select></label><div class="checkgrid">${userPermissionChecks(user)}</div><div class="access-restricted-note">Exclusivas do proprietário: excluir O.S., fechamento/entrega, Financeiro e gerenciamento de usuários.</div><button class="secondary save-user-permissions">Salvar permissões</button></article>`).join('')}</div></section>`;
  $('#backAdmin').onclick=loadDashboard;
  $('#newManagedUser').onsubmit=async event=>{event.preventDefault();const button=event.submitter,permissions=Object.fromEntries([...event.currentTarget.querySelectorAll('[data-user-permission]')].map(input=>[input.dataset.userPermission,input.checked]));button.disabled=true;button.textContent='Cadastrando…';try{managedUsers=await createManagedUser({name:$('#managedUserName').value,email:$('#managedUserEmail').value,password:$('#managedUserPassword').value,agendaMechanic:$('#managedUserMechanic').value,permissions});openUserManager();alert('Usuário cadastrado e permissões salvas.')}catch(error){button.disabled=false;button.textContent='Adicionar usuário';alert(error.message)}};
  document.querySelectorAll('.managed-user-card').forEach(card=>{const email=card.dataset.userEmail,user=managedUsers.find(item=>item.email===email);card.querySelector('.toggle-user-access').onclick=async event=>{event.currentTarget.disabled=true;try{managedUsers=await updateManagedUser(email,{active:!user.active,permissions:{accessApp:!user.active}});openUserManager()}catch(error){event.currentTarget.disabled=false;alert(error.message)}};card.querySelector('.save-user-permissions').onclick=async event=>{const permissions=Object.fromEntries([...card.querySelectorAll('[data-user-permission]')].map(input=>[input.dataset.userPermission,input.checked])),agenda=card.querySelector('.managed-user-mechanic').value;if(email!==FINANCE_EMAIL&&!agenda)return alert('Selecione a agenda do mecânico para este usuário.');event.currentTarget.disabled=true;event.currentTarget.textContent='Salvando…';try{managedUsers=await updateManagedUser(email,{agendaMechanic:agenda,permissions});openUserManager()}catch(error){event.currentTarget.disabled=false;event.currentTarget.textContent='Salvar permissões';alert(error.message)}}})
}
async function loadDashboard(){try{[records,mechanics,managedUsers,costPlans,supplierSettlements,supplierStock]=await Promise.all([readFinance(),readMechanics(),readUserAccess(),readCostPlans(),readSupplierSettlements(),readStock()]);const names=activeMechanics();if(!names.includes(activeMechanic))activeMechanic=names[0]||'';$('#content').innerHTML=dashboardHtml();$('#addMechanic').onclick=openMechanicManager;$('#manageUsers').onclick=openUserManager;document.querySelectorAll('[data-finance-area]').forEach(button=>button.onclick=()=>renderArea(button.dataset.financeArea));renderArea(activeArea)}catch(error){$('#content').innerHTML=`<div class="empty"><h3>Financeiro indisponível</h3><p>${esc(error.message)}</p></div>`}}
function openFinancePopup(area){document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div'),label=area==='Fluxo de caixa'?'Caixa':area;popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><h3>Adicionar em ${label}</h3>${area==='Comissões'?`<p>Mecânico: <b>${activeMechanic}</b></p>`:''}${area==='Fluxo de caixa'?`<label><span>Caixa</span><select id="financePopupAccount">${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label>`:''}<label><span>Data</span><input id="financePopupDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label><span>Registro</span><input id="financePopupDescription" required placeholder="Descrição do lançamento"></label><label><span>Valor</span><input id="financePopupAmount" type="number" min="0.01" step="0.01" required></label>${area==='Fluxo de caixa'?'<label><span>Tipo</span><select id="financePopupKind"><option>Entrada</option><option>Saída</option></select></label><small id="financeAutoKind" hidden>Classificado automaticamente como Saída.</small>':''}<div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Salvar</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();const description=popup.querySelector('#financePopupDescription'),kind=popup.querySelector('#financePopupKind'),note=popup.querySelector('#financeAutoKind'),syncKind=()=>{if(!kind)return;const automatic=automaticCashExpense(description.value);if(automatic)kind.value='Saída';kind.disabled=automatic;if(note)note.hidden=!automatic};description.addEventListener('input',syncKind);popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,dateValue=popup.querySelector('#financePopupDate').value,automatic=area==='Fluxo de caixa'&&automaticCashExpense(description.value);button.disabled=true;try{await saveFinanceRecord({category:area,kind:area==='Fluxo de caixa'?(automatic?'Saída':kind.value):'Saída',description:description.value.trim(),amount:Number(popup.querySelector('#financePopupAmount').value),dueDate:dateValue,status:area==='Fluxo de caixa'?'Realizado':'Pendente',mechanic:area==='Comissões'?activeMechanic:'',paymentType:area==='Fluxo de caixa'?popup.querySelector('#financePopupAccount').value:'',weekStart:area==='Comissões'?monday(dateValue):''});records=await readFinance();popup.remove();await loadDashboard()}catch(error){button.disabled=false;alert(error.message)}}}
function openFinanceForm(){$('#content').innerHTML=`<button class="backlink" id="backAdmin">← Voltar ao financeiro</button><form class="form-card finance-form" id="financeForm"><div class="form-head"><i>R$</i><div><h3>Novo lançamento</h3><p>Caixa, contas e comissões</p></div></div><div class="grid two"><label><span>Área</span><select id="financeCategory"><option>Fluxo de caixa</option><option>Conta a pagar</option><option>Conta a receber</option><option>Comissões</option></select></label><label><span>Movimento</span><select id="financeKind"><option>Entrada</option><option>Saída</option></select></label><label><span>Descrição</span><input id="financeDescription" required></label><label><span>Valor</span><input id="financeAmount" type="number" min="0" step="0.01" required></label><label><span>Vencimento/data</span><input id="financeDue" type="date" required></label><label><span>Status</span><select id="financeStatus"><option>Pendente</option><option>Realizado</option></select></label></div><button class="primary wide">Salvar lançamento</button></form>`;$('#backAdmin').onclick=loadDashboard;$('#financeCategory').onchange=event=>{if(['Conta a pagar','Comissões'].includes(event.target.value))$('#financeKind').value='Saída';if(event.target.value==='Conta a receber')$('#financeKind').value='Entrada'};$('#financeForm').onsubmit=saveFinance}
async function saveFinance(event){event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Salvando…';try{await saveFinanceRecord({category:$('#financeCategory').value,kind:$('#financeKind').value,description:$('#financeDescription').value.trim(),amount:Number($('#financeAmount').value),dueDate:$('#financeDue').value,status:$('#financeStatus').value});loadDashboard()}catch(error){alert(error.message);button.disabled=false;button.textContent='Salvar lançamento'}}
function openPayableSettlement(record){document.querySelector('.finance-popup')?.remove();const popup=document.createElement('div');popup.className='check-popup finance-popup';popup.innerHTML=`<form class="check-popup-card"><span class="eyebrow">BAIXA DE CONTA A PAGAR</span><h3>${esc(record.description)}</h3><p>Confirme o caixa e ajuste o valor realmente pago.</p><label><span>Caixa utilizado</span><select id="payableCashAccount" required>${CASH_ACCOUNTS.map(name=>`<option ${name===activeCashAccount?'selected':''}>${name}</option>`).join('')}</select></label><label><span>Valor pago</span><input id="payablePaidAmount" type="number" min="0.01" step="0.01" value="${Number(record.amount||0).toFixed(2)}" required></label><div class="check-popup-actions"><button type="button" class="secondary cancel-finance-popup">Cancelar</button><button class="primary">Dar baixa e lançar no caixa</button></div></form>`;document.body.append(popup);popup.querySelector('.cancel-finance-popup').onclick=()=>popup.remove();popup.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=event.submitter,account=popup.querySelector('#payableCashAccount').value,amount=Number(popup.querySelector('#payablePaidAmount').value);button.disabled=true;button.textContent='Registrando…';try{await settlePayable(record.id,account,amount);activeCashAccount=account;popup.remove();await loadDashboard()}catch(error){button.disabled=false;button.textContent='Dar baixa e lançar no caixa';alert(error.message)}}}
async function markPaid(id){const record=records.find(item=>item.id===id);if(record?.category==='Conta a pagar')return openPayableSettlement(record);if(!confirm('Marcar este lançamento como realizado?'))return;try{await markFinanceDone(id);await loadDashboard()}catch(error){alert(error.message)}}
function install(){if(getCurrentUser().email.toLowerCase()!==FINANCE_EMAIL){document.querySelectorAll('.admin-route').forEach(button=>button.remove());return}const nav=document.querySelector('aside nav');if(nav&&!nav.querySelector('.admin-route')){const b=document.createElement('button');b.className='admin-route';b.innerHTML='<i>◆</i>Administrativo';b.onclick=openAdmin;nav.append(b)}const mobile=document.querySelector('.mobile-nav');if(mobile&&!mobile.querySelector('.admin-route')){const b=document.createElement('button');b.className='admin-route';b.innerHTML='<i>◆</i><span>Admin</span>';b.onclick=openAdmin;mobile.append(b)}}
new MutationObserver(install).observe(document.querySelector('#app'),{childList:true,subtree:true});install();



